<script setup lang="ts">
import { onMounted, ref } from 'vue';import { apiSeguridad } from '@/utils/seguridad'
const rows=ref<any[]>([]),modulo=ref(''),accion=ref(''),descripcion=ref(''),error=ref('');const cargar=async()=>{try{rows.value=await apiSeguridad('/permisos')}catch(e:any){error.value=e.message}};const guardar=async()=>{try{await apiSeguridad('/permisos',{method:'POST',body:JSON.stringify({modulo:modulo.value,accion:accion.value,descripcion:descripcion.value})});modulo.value=accion.value=descripcion.value='';cargar()}catch(e:any){error.value=e.message}};onMounted(cargar)
</script><template><VCard><VCardItem><VCardTitle>Permisos</VCardTitle></VCardItem><VCardText><VAlert v-if="error" type="error">{{error}}</VAlert><VRow><VCol><VTextField v-model="modulo" label="Módulo"/></VCol><VCol><VTextField v-model="accion" label="Acción"/></VCol><VCol><VTextField v-model="descripcion" label="Descripción"/></VCol><VCol cols="auto"><VBtn @click="guardar">Agregar</VBtn></VCol></VRow><VDataTable :items="rows" :headers="[{title:'Módulo',key:'modulo'},{title:'Acción',key:'accion'},{title:'Descripción',key:'descripcion'}]"/></VCardText></VCard></template>
